import template from './sas-media-upload-v2.html.twig';

export default {
    template,

    props: {
        fileAccept: {
            type: String,
            required: false,
            default: '*/*',
        },

    },

    methods: {
        getMediaEntityForUpload() {
            const mediaItem = this.mediaRepository.create();
            mediaItem.mediaFolderId = this.mediaFolderId;
            mediaItem.private = true;

            return mediaItem;
        },
    },
};
